'use strict';

// MODULES //

var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex64Array = require( '@stdlib/array/complex64' );
var real = require( '@stdlib/complex/float32/real' );
var imag = require( '@stdlib/complex/float32/imag' );
var fcn = require( './assign.js' );


// MAIN //

/**
* Calculates the dot product of two single-precision complex floating-point vectors.
*
* @param {integer} N - number of indexed elements
* @param {Complex64Array} x - first input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64Array} y - second input array
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {Complex64} dot product
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
*
* var x = new Complex64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var y = new Complex64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = cdotu( 3, x, 1, 0, y, 1, 0 );
* // returns <Complex64>[ -52.0, 82.0 ]
*/
function cdotu( N, x, strideX, offsetX, y, strideY, offsetY ) {
	var out = new Complex64Array( 1 );
	fcn( N, x, strideX, offsetX, y, strideY, offsetY, out, 0 );

	return new Complex64( real( out.get( 0 ) ), imag( out.get( 0 ) ) );
}


// EXPORTS //

module.exports = cdotu;
